                String name = page.getFileName().toString().replaceFirst("\\.mdx$", "");
                assertTrue(front.contains("id: " + MOD_ID + ":" + name), page + " needs id: " + MOD_ID + ":" + name);
                assertTrue(front.contains("type: block"), page + " needs type: block");
            }
        }
    }

