        assertTrue(!lines.isEmpty() && lines.get(0).equals("---"), page + " must open with ---");
        int end = lines.subList(1, lines.size()).indexOf("---");
        assertTrue(end >= 0, page + " frontmatter is not closed");
        return lines.subList(1, end + 1);
    }
}
